candyBooth = {
  const rng = makeRng(Date.now() &gt;&gt;&gt; 0);
  // Hidden mean sweets per pull; green is best, as in the story.
  const machines = [
    {name: "Red", cls: "red", mean: 2.0},
    {name: "Blue", cls: "blue", mean: 2.6},
    {name: "Green", cls: "green", mean: 4.8}
  ];
  let N, Q, total, pulls, last, revealed;
  const root = html`&lt;div&gt;
    &lt;div class="rl-widget-title"&gt;Three candy machines&lt;/div&gt;
    &lt;div class="rl-machines"&gt;&lt;/div&gt;
    &lt;div class="rl-stats"&gt;&lt;/div&gt;
    &lt;div&gt;
      &lt;button data-act="ada"&gt;Ada's rule: 1 pull&lt;/button&gt;
      &lt;button data-act="ada10"&gt;Ada's rule: 10 pulls&lt;/button&gt;
      &lt;button data-act="reveal"&gt;Reveal true averages&lt;/button&gt;
      &lt;button data-act="reset"&gt;Reset&lt;/button&gt;
    &lt;/div&gt;
    &lt;p class="rl-note"&gt;Sweets per pull are a rounded Gaussian (sd 1.5) around each machine's hidden average.&lt;/p&gt;
  &lt;/div&gt;`;
  const row = root.querySelector(".rl-machines");
  const stats = root.querySelector(".rl-stats");
  const buttons = machines.map((m, a) =&gt; {
    const b = html`&lt;button class="rl-machine ${m.cls}"&gt;&lt;/button&gt;`;
    b.onclick = () =&gt; { pull(a); render(); };
    row.append(b);
    return b;
  });
  const reset = () =&gt; {
    N = [0, 0, 0]; Q = [0, 0, 0]; total = 0; pulls = 0; last = null; revealed = false;
  };
  const pull = (a) =&gt; {
    const sweets = Math.max(0, Math.round(rng.normal(machines[a].mean, 1.5)));
    N[a] += 1;
    Q[a] += (sweets - Q[a]) / N[a];
    total += sweets;
    pulls += 1;
    last = {a, sweets};
  };
  const adaPull = () =&gt; {
    // Untried machines first, then epsilon-greedy on the napkin averages.
    const untried = [0, 1, 2].filter((a) =&gt; N[a] === 0);
    const a = untried.length ? untried[0]
      : rng.random() &lt; 0.1 ? rng.int(3) : argmaxRandom(Q, rng);
    pull(a);
  };
  const render = () =&gt; {
    buttons.forEach((b, a) =&gt; {
      const m = machines[a];
      b.classList.toggle("last", last !== null && last.a === a);
      b.innerHTML = `&lt;div class="rl-machine-name"&gt;${m.name}&lt;/div&gt;
        &lt;div&gt;N = ${N[a]}&lt;/div&gt;
        &lt;div&gt;Q = ${N[a] ? Q[a].toFixed(2) : "–"}&lt;/div&gt;
        ${revealed ? `&lt;div&gt;q* = ${m.mean.toFixed(1)}&lt;/div&gt;` : ""}`;
    });
    stats.innerHTML = pulls === 0
      ? "Click a machine to spend a token."
      : `Pull ${pulls}: &lt;b&gt;${machines[last.a].name}&lt;/b&gt; dropped ${last.sweets} sweet${last.sweets === 1 ? "" : "s"}.
         Total ${total} sweets, ${(total / pulls).toFixed(2)} per token
         (best possible on average: ${machines[2].mean.toFixed(1)}).`;
  };
  root.onclick = (e) =&gt; {
    const act = e.target.dataset?.act;
    if (!act) return;
    if (act === "ada") adaPull();
    if (act === "ada10") for (let i = 0; i &lt; 10; i++) adaPull();
    if (act === "reveal") revealed = !revealed;
    if (act === "reset") reset();
    render();
  };
  reset();
  render();
  return root;
}









